 {Bytes ram=base_ram("");put(ram,NODE+0x36,4,0x80000000);State s=st(0x20de6);check(runs_to(ram,s,STOP)&&get(ram,NODE+0x36,4)==0x7c000000U&&get(ram,NODE+0x3a,4)==0x1800U,"20de6 sign");}
